sp_widget.client_script:
api.controller = function() {
    /* widget controller */

    var c = this;

    // 1. Initialize loading flag
    c.isLoading = true; // Set to true initially

    c.errorList = c.data.errorList ? c.data.errorList : []; // Check if input exists

    // 2. Set loading flag to false once c.errorList has been assigned (data loaded)
    c.isLoading = false; // Data is now available

    // You might also want to display a message if errorList is empty
    c.noErrorsMessage = (c.errorList && c.errorList.length === 0) ? "The file you have uploaded does not hold any data. Please reupload" : "";


	//testing

    // Determine if errors were found
    c.hasErrors = c.errorList.length > 0;

    // You might also want to display a message if errorList is empty
    c.noErrorsMessage = (c.errorList && c.errorList.length === 0) ? "No validation errors found. You can proceed." : "";


    console.log("Error List in Client Controller:"+  c.hasErrors); // For debugging




};

